# TypeScript User Interface with Runtime Validation

```typescript
// user.ts

export interface User {
  id: number;
  email: string;
  name?: string;
}

/**
 * Type guard that validates an unknown value against the User interface.
 * Returns `true` if the value is a valid User, narrowing the type.
 */
export function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const obj = value as Record<string, unknown>;

  // Required: id must be a number (and finite, to reject NaN/Infinity)
  if (typeof obj.id !== "number" || !Number.isFinite(obj.id)) {
    return false;
  }

  // Required: email must be a non-empty string
  if (typeof obj.email !== "string" || obj.email.length === 0) {
    return false;
  }

  // Optional: name, if present, must be a string
  if (obj.name !== undefined && typeof obj.name !== "string") {
    return false;
  }

  return true;
}

